// @ts-nocheck -- route types are generated by the embedded app.
// Plan-builder home: the cohort groups list + the create-group step.
// Creating a group persists a DRAFT immediately (name/programme/months) and
// jumps into the group workspace where members and the plan are built.
import { useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { createFileRoute, Link, useNavigate } from "@tanstack/react-router";
import { ArrowLeft, BookOpenText, ChevronDown, ChevronRight, Plus, UsersRound, X } from "lucide-react";
import Swal from "sweetalert2";
import { Button } from "@/features/audit/learner-log-pro-manual/components/ui/button";
import {
  createPlanGroup,
  listPlanGroups,
  pickAptemGroups,
  pickAptemProgrammes,
  pickTrainingPlan,
} from "@/features/audit/learner-log-pro-manual/lib/plan-api";

export const Route = createFileRoute("/groups")({
  component: GroupsPage,
});

const field =
  "h-9 w-full rounded-md border border-border bg-card px-2.5 text-sm text-foreground outline-none focus:border-primary";

function statusChip(status: string) {
  if (status === "active") return "bg-success/10 text-success";
  if (status === "draft") return "bg-warning/20 text-foreground ring-1 ring-warning/40";
  return "bg-muted text-muted-foreground";
}

// The programme's GENERAL training plan (months -> modules from Aptem),
// opened from the programme header. Individual learners share these names
// with their own shifted dates — that per-learner view is the next step.
function TrainingPlanModal({ programme, onClose }: { programme: string; onClose: () => void }) {
  const plan = useQuery({
    queryKey: ["plan-training-plan", programme],
    queryFn: () => pickTrainingPlan(programme),
  });
  const months = plan.data?.months ?? [];
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4" onClick={onClose}>
      <div className="max-h-[85vh] w-full max-w-3xl overflow-auto rounded-lg border border-border bg-card shadow-panel" onClick={(event) => event.stopPropagation()}>
        <header className="sticky top-0 flex items-center justify-between border-b border-border bg-card px-6 py-4">
          <div>
            <h2 className="font-serif text-base text-foreground">Training plan — {programme}</h2>
            {plan.data && (
              <p className="mt-0.5 text-xs text-muted-foreground">
                General plan shared by {plan.data.majority_count ?? 0} of {plan.data.learners_with_plan} learners · {plan.data.total_modules ?? 0} modules
              </p>
            )}
          </div>
          <button type="button" onClick={onClose} className="rounded p-1.5 text-muted-foreground hover:bg-secondary"><X className="h-4 w-4" /></button>
        </header>
        <div className="px-6 py-4">
          {plan.isLoading && <p className="py-8 text-center text-sm text-muted-foreground">Loading the training plan…</p>}
          {!plan.isLoading && months.length === 0 && (
            <p className="py-8 text-center text-sm text-muted-foreground">No Aptem training plan found for this programme&apos;s learners.</p>
          )}
          {months.map((month, index) => (
            <details key={index} className="mb-2 rounded-lg border border-border" open={index === 0}>
              <summary className="cursor-pointer bg-[#eef3f8] px-4 py-2.5 text-xs font-semibold uppercase tracking-wider text-[#182d48]">
                {month.month ?? `Month ${index + 1}`}{month.date ? ` · ${month.date}` : ""} — {month.modules.length} modules
              </summary>
              <ul className="divide-y divide-border">
                {month.modules.map((module, moduleIndex) => (
                  <li key={moduleIndex} className="flex flex-wrap items-center gap-3 px-4 py-2">
                    <span className="min-w-0 flex-1 truncate text-sm text-foreground" title={module.name ?? ""}>{module.name ?? "Untitled module"}</span>
                    {module.type && <span className="rounded bg-secondary px-1.5 py-0.5 text-[10px] font-medium text-muted-foreground">{module.type}</span>}
                    {module.status && (
                      <span className={`rounded-full px-2 py-0.5 text-[10px] font-semibold ${String(module.status).toLowerCase() === "completed" ? "bg-success/10 text-success" : "bg-muted text-muted-foreground"}`}>
                        {module.status}
                      </span>
                    )}
                  </li>
                ))}
              </ul>
            </details>
          ))}
        </div>
      </div>
    </div>
  );
}

// One programme row in the Aptem accordion: click to expand its Aptem groups;
// each group either opens its existing plan or creates one in a single click.
function ProgrammeSection({ programme, planGroups, open, onToggle, onChanged }: {
  programme: { programme: string; aptem_learners: number; in_cohort: number };
  planGroups: Array<{ id: number; name: string; aptem_group?: string | null; status: string; member_count?: number; activity_count?: number }>;
  open: boolean;
  onToggle: () => void;
  onChanged: () => Promise<unknown> | unknown;
}) {
  const navigate = useNavigate();
  const [creatingFor, setCreatingFor] = useState("");
  const [showTrainingPlan, setShowTrainingPlan] = useState(false);
  const aptemGroups = useQuery({
    queryKey: ["plan-aptem-groups", programme.programme],
    queryFn: () => pickAptemGroups(programme.programme),
    enabled: open,
  });

  async function createFor(group: { name: string; aptemGroup?: string }) {
    setCreatingFor(group.name);
    try {
      const created = await createPlanGroup({
        name: group.name,
        kind: "cohort",
        programme_name: programme.programme,
        aptem_group: group.aptemGroup ?? null,
        months_from_training_plan: true,
      });
      await onChanged();
      void Swal.fire({
        toast: true, position: "top-end", icon: "success",
        title: `Plan created — ${created.members?.length ?? 0} learners, ${created.months?.length ?? 0} months`,
        showConfirmButton: false, timer: 2200,
      });
      navigate({ to: "/groups/$groupId", params: { groupId: String(created.id) } });
    } catch (cause) {
      await Swal.fire({ icon: "error", title: "Could not create the plan", text: cause instanceof Error ? cause.message : "Unexpected error." });
    } finally {
      setCreatingFor("");
    }
  }

  // Plans link to Aptem groups by the stored aptem_group (name fallback for
  // groups created before the linkage column existed).
  const planFor = (group: string) =>
    planGroups.find((item) => item.aptem_group === group) ?? planGroups.find((item) => item.name === group);
  const aptemNames = new Set((aptemGroups.data?.items ?? []).map((item) => item.group));
  const customPlans = planGroups.filter((item) => !aptemNames.has(item.aptem_group ?? item.name));

  return (
    <div>
      <button
        type="button"
        onClick={onToggle}
        className="flex w-full items-center gap-3 px-7 py-4 text-left transition-colors hover:bg-secondary/40"
      >
        {open ? <ChevronDown className="h-4 w-4 text-muted-foreground" /> : <ChevronRight className="h-4 w-4 text-muted-foreground" />}
        <span className="min-w-0 flex-1">
          <span className="block truncate text-sm font-semibold text-foreground">{programme.programme}</span>
          <span className="text-xs text-muted-foreground">
            {programme.aptem_learners} Aptem learners
            {planGroups.length > 0 ? ` · ${planGroups.length} plan${planGroups.length === 1 ? "" : "s"}` : ""}
          </span>
        </span>
        {planGroups.some((item) => item.status === "active") && (
          <span className="rounded-full bg-success/10 px-2.5 py-1 text-xs font-semibold text-success">active plans</span>
        )}
        <span
          role="button"
          tabIndex={0}
          title="The programme's general training plan (from Aptem)"
          onClick={(event) => { event.stopPropagation(); setShowTrainingPlan(true); }}
          onKeyDown={(event) => { if (event.key === "Enter") { event.stopPropagation(); setShowTrainingPlan(true); } }}
          className="inline-flex items-center gap-1.5 rounded-md border border-border bg-card px-2.5 py-1.5 text-xs font-semibold text-foreground transition-colors hover:bg-secondary"
        >
          <BookOpenText className="h-3.5 w-3.5" /> Training plan
        </span>
      </button>
      {showTrainingPlan && <TrainingPlanModal programme={programme.programme} onClose={() => setShowTrainingPlan(false)} />}
      {open && (
        <div className="space-y-1 pb-4 pl-14 pr-7">
          {aptemGroups.isLoading && <p className="py-3 text-xs text-muted-foreground">Loading groups…</p>}
          {(aptemGroups.data?.items ?? []).map((item) => {
            const plan = planFor(item.group);
            return (
              <div key={item.group} className="flex flex-wrap items-center gap-3 rounded-md border border-border bg-card px-4 py-2.5">
                <div className="min-w-0 flex-1">
                  <p className="truncate text-sm font-medium text-foreground">{item.group}</p>
                  <p className="text-xs text-muted-foreground">
                    <UsersRound className="mr-1 inline h-3 w-3" />
                    {item.aptem_learners} learners
                    {plan ? ` · ${plan.activity_count ?? 0} activities planned` : ""}
                  </p>
                </div>
                {plan ? (
                  <>
                    <span className={`rounded-full px-2.5 py-1 text-xs font-semibold ${statusChip(plan.status)}`}>{plan.status}</span>
                    <Link
                      to="/groups/$groupId"
                      params={{ groupId: String(plan.id) }}
                      className="inline-flex items-center gap-1.5 rounded-md border border-border bg-card px-2.5 py-1.5 text-xs font-semibold text-foreground transition-colors hover:bg-secondary"
                    >
                      Open plan <ArrowLeft className="h-3.5 w-3.5 rotate-180" />
                    </Link>
                  </>
                ) : (
                  <Button size="sm" variant="outline" disabled={creatingFor === item.group} onClick={() => void createFor({ name: item.group, aptemGroup: item.group })}>
                    <Plus className="mr-1 h-3.5 w-3.5" /> {creatingFor === item.group ? "Creating…" : "Create plan"}
                  </Button>
                )}
              </div>
            );
          })}
          {customPlans.map((plan) => (
            <div key={plan.id} className="flex flex-wrap items-center gap-3 rounded-md border border-border bg-card px-4 py-2.5">
              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-medium text-foreground">{plan.name}</p>
                <p className="text-xs text-muted-foreground">custom group · {plan.member_count ?? 0} members</p>
              </div>
              <span className={`rounded-full px-2.5 py-1 text-xs font-semibold ${statusChip(plan.status)}`}>{plan.status}</span>
              <Link
                to="/groups/$groupId"
                params={{ groupId: String(plan.id) }}
                className="inline-flex items-center gap-1.5 rounded-md border border-border bg-card px-2.5 py-1.5 text-xs font-semibold text-foreground transition-colors hover:bg-secondary"
              >
                Open plan <ArrowLeft className="h-3.5 w-3.5 rotate-180" />
              </Link>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function GroupsPage() {
  const queryClient = useQueryClient();
  const navigate = useNavigate();
  const [creating, setCreating] = useState(false);
  const [saving, setSaving] = useState(false);
  const [name, setName] = useState("");
  const [programme, setProgramme] = useState("");
  const [startMonth, setStartMonth] = useState("");
  const [monthsCount, setMonthsCount] = useState(12);
  const [aptemGroup, setAptemGroup] = useState("");

  const groups = useQuery({ queryKey: ["plan-groups"], queryFn: listPlanGroups });
  // Aptem is the source of truth: programmes with Aptem counts, and each
  // programme's groups from Aptem's own Group field.
  const programmes = useQuery({ queryKey: ["plan-aptem-programmes"], queryFn: pickAptemProgrammes });
  const aptemGroups = useQuery({
    queryKey: ["plan-aptem-groups", programme],
    queryFn: () => pickAptemGroups(programme),
    enabled: Boolean(programme),
  });

  async function create() {
    if (!name.trim() && !aptemGroup) {
      return void Swal.fire({ icon: "error", title: "Name the group", text: "Pick an Aptem group or type a name (e.g. October Group)." });
    }
    setSaving(true);
    try {
      // One call does it all: the Aptem group's learners are assigned, the
      // months come from their training plans (majority = the group months),
      // and every learner whose own plan differs keeps THEIR dates.
      const created = await createPlanGroup({
        name: name.trim() || aptemGroup || "New group",
        kind: "cohort",
        programme_name: programme.trim() || null,
        aptem_group: aptemGroup || null,
        months_from_training_plan: Boolean(aptemGroup),
        start_month: aptemGroup ? null : startMonth || null,
        months_count: !aptemGroup && startMonth ? monthsCount : 0,
      });
      await queryClient.invalidateQueries({ queryKey: ["plan-groups"] });
      void Swal.fire({
        toast: true, position: "top-end", icon: "success",
        title: created.members?.length
          ? `Group created — ${created.members.length} learners assigned, ${created.months?.length ?? 0} plan months`
          : "Draft group created",
        showConfirmButton: false, timer: 2400,
      });
      navigate({ to: "/groups/$groupId", params: { groupId: String(created.id) } });
    } catch (cause) {
      await Swal.fire({ icon: "error", title: "Could not create the group", text: cause instanceof Error ? cause.message : "Unexpected error." });
    } finally {
      setSaving(false);
    }
  }

  // Individual plans (groups of one) live on the learner pages — the cohort
  // list stays clean, exactly as the design review required.
  const visibleGroups = (groups.data?.items ?? []).filter((group) => group.kind === "cohort");
  // Aptem hierarchy: the FULL programme name (cohort included) is the section;
  // its groups are exactly the ones Aptem links to that name.
  const byProgramme = visibleGroups.reduce<Record<string, typeof visibleGroups>>((acc, group) => {
    const key = group.programme_name || "No programme";
    (acc[key] = acc[key] ?? []).push(group);
    return acc;
  }, {});
  const [openProgrammes, setOpenProgrammes] = useState<Record<string, boolean>>({});

  return (
    <div className="min-h-screen bg-background">
      <header className="border-b border-border bg-surface">
        <div className="mx-auto flex max-w-[1700px] flex-wrap items-center justify-between gap-4 px-6 py-4">
          <div className="flex items-baseline gap-3">
            <span className="font-serif text-base text-foreground">OTJ&nbsp;Ledger</span>
            <span className="label-caps">Plan builder — groups</span>
          </div>
          <div className="flex items-center gap-4 text-xs text-muted-foreground">
            <Link to="/search" className="font-medium hover:underline">Learner search</Link>
            <Link to="/activity" search={{ learner: "" }} className="font-medium hover:underline">Activity log</Link>
            <Link to="/journal" search={{ learner: "", period: "" }} className="font-medium hover:underline">Monthly journal</Link>
          </div>
        </div>
      </header>

      <main className="mx-auto w-full max-w-[1300px] space-y-6 px-6 py-8">
        <section className="rounded-lg border border-border bg-card shadow-panel">
          <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-7 py-5">
            <div>
              <h1 className="font-serif text-lg text-foreground">Groups</h1>
              <p className="mt-1 text-sm text-muted-foreground">
                One plan per group — every member shares it; only per-learner progress differs.
              </p>
            </div>
            <Button size="sm" onClick={() => setCreating((value) => !value)}>
              <Plus className="mr-1.5 h-3.5 w-3.5" /> New group
            </Button>
          </header>

          {creating && (
            <div className="border-b border-border bg-secondary/40 px-7 py-5">
              <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
                {/* 1) Programme from Aptem -> 2) only ITS groups appear -> pick
                    one and its learners are assigned with the months coming
                    from their own training plans. */}
                <label className="block">
                  <span className="label-caps">1 · Programme (Aptem)</span>
                  <select
                    className={`${field} mt-1.5`}
                    value={programme}
                    onChange={(e) => { setProgramme(e.target.value); setAptemGroup(""); }}
                  >
                    <option value="">— choose programme —</option>
                    {(programmes.data?.items ?? []).map((option) => (
                      <option key={option.programme} value={option.programme}>
                        {option.programme} ({option.aptem_learners})
                      </option>
                    ))}
                  </select>
                </label>
                <label className="block">
                  <span className="label-caps">2 · Aptem group inside it</span>
                  <select
                    className={`${field} mt-1.5`}
                    value={aptemGroup}
                    disabled={!programme}
                    onChange={(e) => {
                      setAptemGroup(e.target.value);
                      if (e.target.value && !name.trim()) setName(e.target.value);
                    }}
                  >
                    <option value="">{programme ? "— choose group (auto-assigns its learners) —" : "pick a programme first"}</option>
                    {(aptemGroups.data?.items ?? []).map((option) => (
                      <option key={option.group} value={option.group}>
                        {option.group} ({option.aptem_learners})
                      </option>
                    ))}
                  </select>
                </label>
                <label className="block">
                  <span className="label-caps">Group name</span>
                  <input className={`${field} mt-1.5`} placeholder="auto-filled from the group" value={name} onChange={(e) => setName(e.target.value)} />
                </label>
                <div className="block">
                  <span className="label-caps">&nbsp;</span>
                  <div className="mt-1.5">
                    <Button size="sm" disabled={saving} onClick={() => void create()}>
                      {saving ? "Creating…" : "Create group"}
                    </Button>
                  </div>
                </div>
              </div>
              {aptemGroup ? (
                <p className="mt-3 text-xs text-muted-foreground">
                  Months will be built from the members&apos; Aptem training plans — the group carries the majority window, and every learner whose own plan differs keeps their own dates automatically.
                </p>
              ) : (
                <div className="mt-3 flex flex-wrap items-end gap-4">
                  <p className="text-xs text-muted-foreground">No LMS group? Set the months manually:</p>
                  <label className="block">
                    <span className="label-caps">Start month</span>
                    <input type="month" className={`${field} mt-1 w-44`} value={startMonth} onChange={(e) => setStartMonth(e.target.value)} />
                  </label>
                  <label className="block">
                    <span className="label-caps">Months</span>
                    <input type="number" min={1} max={48} className={`${field} mt-1 w-24`} value={monthsCount} onChange={(e) => setMonthsCount(Number(e.target.value) || 1)} />
                  </label>
                </div>
              )}
            </div>
          )}

          {groups.isError ? (
            <p className="px-7 py-10 text-center text-sm text-destructive">
              {groups.error instanceof Error ? groups.error.message : "Could not load groups."}
            </p>
          ) : programmes.isLoading || groups.isLoading ? (
            <p className="px-7 py-10 text-center text-sm text-muted-foreground">Loading programmes…</p>
          ) : (
            <div className="divide-y divide-border">
              {(programmes.data?.items ?? []).map((prog) => (
                <ProgrammeSection
                  key={prog.programme}
                  programme={prog}
                  planGroups={byProgramme[prog.programme] ?? []}
                  open={!!openProgrammes[prog.programme]}
                  onToggle={() => setOpenProgrammes((s) => ({ ...s, [prog.programme]: !s[prog.programme] }))}
                  onChanged={() => queryClient.invalidateQueries({ queryKey: ["plan-groups"] })}
                />
              ))}
            </div>
          )}
        </section>
      </main>
    </div>
  );
}
